    public Account updateAccount( UpdateAccountCommand command ) 
    throws ProcessingException, IllegalArgumentException {

	    Account entity = new Account();

    	try {       

			// --------------------------------------
        	// validate 
        	// --------------------------------------    	
        	AccountValidator.getInstance().validate( command );    

            entity.setAccountId( command.getAccountId() );
            entity.setName( command.getName() );
            entity.setAccountNumber( command.getAccountNumber() );
            entity.setBaseCurrency( command.getBaseCurrency() );
            entity.setOpenedDate( command.getOpenedDate() );
            entity.setHousehold( command.getHousehold() );
            entity.setAdvisor( command.getAdvisor() );
            entity.setCustodian( command.getCustodian() );
            entity.setPortfolio( command.getPortfolio() );
            entity.setBeneficiaries( command.getBeneficiaries() );
            entity.setPositions( command.getPositions() );
            entity.setTransactions( command.getTransactions() );
            entity.setFees( command.getFees() );
            entity.setStandingInstructions( command.getStandingInstructions() );
            entity.setInvoices( command.getInvoices() );
            entity.setAccountType( command.getAccountType() );
            entity.setRegistrationType( command.getRegistrationType() );
            entity.setStatus( command.getStatus() );
        	
        	// ------------------------------------------
        	// persist an existing one
        	// ------------------------------------------ 
        	entity = projector.update(entity);
    	    
			LOGGER.info( "done saving of Account {0} ", entity.toString() );
    	}
        catch (Exception exc) {
            final String errMsg = "Unable to save Account - " + exc;
            LOGGER.warn( errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
    	
    	return entity;
    }
   
